#!/usr/bin/env python3
"""Send lines to `executable mcp [args]` and show stdout lines, stderr and exit code.
usage: rpc.py [-m] [-b] [-a 'args'] [-d dir] [-t trunc] [-n] line...
Each line arg is sent verbatim (a newline added). '@init' expands to the initialize request,
'@inited' to notifications/initialized.
-m: use MINE instead of original. -b: run both and diff. -n: no final newline.
"""
import os, sys, subprocess, json, tempfile, shlex
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a72bc6bb3098c35fb/target/release/bimcraft-cli')
INIT = '{"jsonrpc":"2.0","id":0,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"t","version":"1"}}}'


def run(exe, args, data, cwd, env):
    p = subprocess.run([exe, 'mcp'] + args, input=data, capture_output=True, cwd=cwd, env=env, timeout=120)
    return p


def show(p, trunc):
    out = p.stdout.decode('utf-8', 'replace')
    for l in out.split('\n'):
        if l == '':
            continue
        if trunc and len(l) > trunc:
            l = l[:trunc] + '...(%d)' % len(l)
        print('OUT:', l)
    if p.stderr:
        e = p.stderr.decode('utf-8', 'replace')
        print('ERR:', e, end='' if e.endswith('\n') else '\n')
    print('EXIT:', p.returncode)


def main():
    a = sys.argv[1:]
    exe = ORIG
    args = []
    both = False
    trunc = 600
    cwd = None
    nonl = False
    while a and a[0].startswith('-') and len(a[0]) == 2:
        if a[0] == '-m':
            exe = MINE; a = a[1:]
        elif a[0] == '-b':
            both = True; a = a[1:]
        elif a[0] == '-a':
            args = shlex.split(a[1]); a = a[2:]
        elif a[0] == '-t':
            trunc = int(a[1]); a = a[2:]
        elif a[0] == '-d':
            cwd = a[1]; a = a[2:]
        elif a[0] == '-n':
            nonl = True; a = a[1:]
        else:
            break
    lines = []
    for x in a:
        if x == '@init':
            lines.append(INIT)
        elif x == '@inited':
            lines.append('{"jsonrpc":"2.0","method":"notifications/initialized"}')
        else:
            lines.append(x)
    data = ('\n'.join(lines) + ('' if nonl else '\n')).encode()
    env = dict(os.environ)
    if both:
        d1 = cwd or tempfile.mkdtemp(prefix='rpcA')
        d2 = tempfile.mkdtemp(prefix='rpcB')
        if cwd:
            import shutil
            shutil.rmtree(d2)
            shutil.copytree(cwd, d2)
        p1 = run(ORIG, args, data, d1, env)
        p2 = run(MINE, args, data, d2, env)
