"""list_commands with various filters: print ids (or the text if not a list)."""
import subprocess, json, sys, os
exe = os.environ.get('EXE', '/workspace/executable')
filters = sys.argv[1:]
lines = []
for i, f in enumerate(filters):
    args = {} if f == '@none' else {"filter": json.loads(f)}
    lines.append(json.dumps({"jsonrpc": "2.0", "id": i, "method": "tools/call", "params": {"name": "list_commands", "arguments": args}}))
p = subprocess.run([exe, 'mcp'], input=('\n'.join(lines) + '\n').encode(), capture_output=True)
