for f, l in zip(filters, p.stdout.decode().splitlines()):
    v = json.loads(l)
    if 'error' in v:
        print(f, 'ERROR', v['error'])
        continue
    r = v['result']
    t = r['content'][0]['text']
    try:
        d = json.loads(t)
    except Exception:
        print(f, 'TEXT', repr(t[:300]), r.get('isError'))
        continue
    if isinstance(d, list):
        print(f, len(d), [c['id'] for c in d][:40], r.get('isError'))
    else:
        print(f, 'OBJ', json.dumps(d)[:300], r.get('isError'))

