#!/usr/bin/env python3
"""A fake BIMCraft window control port.

usage: fakewin.py PORTFILE LOGFILE ACTIONS_JSON
  Listens on 127.0.0.1 (any free port), writes the port to PORTFILE, logs every connection's
  received bytes (repr per chunk and per line) to LOGFILE.
  ACTIONS_JSON: a JSON list; for each line received (in order, across connections), the next action:
    a string  -> sent verbatim (add your own \n)
    {"close": true} -> close the connection (no reply)
    {"sleep": secs, "then": action} -> sleep then do action
    {"noreply": true} -> send nothing, keep reading
    {"raw_hex": "..."} -> send bytes
    {"echo": true} -> reply {"ok":true,"result":<the request>}
  When actions run out: the default action (last item of ACTIONS_JSON if it is {"default": action}) or noreply.
"""
import socket, sys, json, threading, time, os

portfile, logfile, actions_s = sys.argv[1], sys.argv[2], sys.argv[3]
actions = json.loads(open(actions_s).read() if os.path.exists(actions_s) else actions_s)
default = None
if actions and isinstance(actions[-1], dict) and 'default' in actions[-1]:
    default = actions[-1]['default']
    actions = actions[:-1]
lock = threading.Lock()
log = open(logfile, 'a')


def L(s):
    with lock:
        log.write(s + '\n')
        log.flush()


def next_action():
    with lock:
        if actions:
            return actions.pop(0)
        return default if default is not None else {"noreply": True}


def do(conn, act, line, n):
    if isinstance(act, str):
        conn.sendall(act.encode())
        L('C%d SENT %r' % (n, act))
        return True
    if 'close' in act:
        L('C%d CLOSE' % n)
        try:
            conn.shutdown(socket.SHUT_RDWR)
        except Exception:
            pass
        conn.close()
        return False
    if 'sleep' in act:
        time.sleep(act['sleep'])
        return do(conn, act['then'], line, n)
    if 'noreply' in act:
        L('C%d NOREPLY' % n)
        return True
    if 'raw_hex' in act:
        conn.sendall(bytes.fromhex(act['raw_hex']))
        L('C%d SENT HEX %s' % (n, act['raw_hex']))
        return True
    if 'echo' in act:
        try:
            req = json.loads(line)
        except Exception:
            req = line.decode('utf-8', 'replace')
        s = json.dumps({"ok": True, "result": req}) + '\n'
        conn.sendall(s.encode())
        L('C%d SENT %r' % (n, s))
        return True
    return True


cnt = [0]


def handle(conn, n):
    buf = b''
    L('C%d OPEN' % n)
    try:
        while True:
            d = conn.recv(65536)
            if not d:
                L('C%d EOF (pending %r)' % (n, buf))
                break
            L('C%d RECV %r' % (n, d))
            buf += d
            while b'\n' in buf:
                line, buf = buf.split(b'\n', 1)
                L('C%d LINE %s' % (n, line.decode('utf-8', 'replace')))
                act = next_action()
                if not do(conn, act, line, n):
                    return
    except Exception as e:
        L('C%d EXC %r' % (n, e))
    finally:
        try:
            conn.close()
        except Exception:
            pass


s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(('127.0.0.1', int(os.environ.get('FAKEPORT', '0'))))
s.listen(16)
open(portfile, 'w').write(str(s.getsockname()[1]))
while True:
    c, a = s.accept()
    cnt[0] += 1
    threading.Thread(target=handle, args=(c, cnt[0]), daemon=True).start()

