#!/usr/bin/env python3
"""For each render param set: the raw `render` command result (execute) and the render tool's content.
usage: render_cmp.py [-s setup_script_line]... paramsjson...
"""
import subprocess, json, sys, tempfile, os
a = sys.argv[1:]
setup = []
args = os.environ.get('ARGS', '').split()
while a and a[0] == '-s':
    setup.append(a[1]); a = a[2:]
lines = []
n = 0
for s in setup:
    lines.append(json.dumps({"jsonrpc": "2.0", "id": "setup%d" % n, "method": "tools/call", "params": {"name": "script", "arguments": {"text": s}}}))
    n += 1
for i, ps in enumerate(a):
    p = json.loads(ps)
    lines.append(json.dumps({"jsonrpc": "2.0", "id": "x%d" % i, "method": "tools/call", "params": {"name": "execute", "arguments": {"command": "render", "params": p}}}))
    lines.append(json.dumps({"jsonrpc": "2.0", "id": "t%d" % i, "method": "tools/call", "params": {"name": "render", "arguments": p}}))
d = os.environ.get('CWD') or tempfile.mkdtemp(prefix='rc')
pr = subprocess.run(['/workspace/executable', 'mcp'] + args, input=('\n'.join(lines) + '\n').encode(), capture_output=True, cwd=d, timeout=600)
res = {}
for l in pr.stdout.decode().splitlines():
    v = json.loads(l)
    res[v['id']] = v
for k in list(res):
    if str(k).startswith('setup'):
        r = res[k]
        if 'error' in r or r['result'].get('isError'):
            print('SETUP FAIL', k, json.dumps(r)[:500])
for i, ps in enumerate(a):
    x = res.get('x%d' % i); t = res.get('t%d' % i)
    print('PARAMS', ps)
    if x is None:
        print('  no reply')
        continue
    xr = x.get('result', x.get('error'))
    if 'content' in xr:
        txt = xr['content'][0]['text']
        try:
            v = json.loads(txt)
            if isinstance(v, dict) and 'pngBase64' in v:
                v['pngBase64'] = '<%d b64>' % len(v['pngBase64'])
            if isinstance(v, dict) and 'svg' in v:
                v['svg'] = '<%d svg>' % len(v['svg'])
            print('  EXEC', 'ERR' if xr.get('isError') else 'OK', json.dumps(v, ensure_ascii=False)[:1500])
        except Exception:
            print('  EXEC', 'ERR' if xr.get('isError') else 'OK', txt[:500])
    else:
        print('  EXEC RPC', xr)
    tr = t.get('result', t.get('error'))
    if 'content' in tr:
        cs = []
        for c in tr['content']:
            c = dict(c)
            if 'data' in c:
                c['data'] = '<%d b64%s>' % (len(c['data']), ' SAME' if xr.get('content') and 'pngBase64' in xr['content'][0]['text'] and c['data'] in xr['content'][0]['text'] else '')
            cs.append(c)
        print('  TOOL', 'ERR' if tr.get('isError') else 'OK', json.dumps(cs, ensure_ascii=False)[:1500], {k: v for k, v in tr.items() if k not in ('content', 'isError')})
    else:
        print('  TOOL RPC', tr)
if pr.stderr:
    print('STDERR', pr.stderr.decode()[:2000])

