#!/usr/bin/env python3
"""Bridge scenario: pairs of (tool call, window reply).
usage: brs.py [-m] [-a extra] TOOL ARGS_JSON REPLY_LINE [TOOL ARGS_JSON REPLY_LINE]...
  REPLY_LINE is sent verbatim + \n (or '@close', '@noreply', '@sleep:N:line').
Prints the MCP output lines (data elided), stderr, exit, and the lines the window received.
"""
import subprocess, sys, json, os
a = sys.argv[1:]
pre = []
while a and a[0] in ('-m', '-a', '-c', '-j', '-w', '-t'):
    if a[0] == '-m':
        pre.append(a[0]); a = a[1:]
    else:
        pre += a[:2]; a = a[2:]
hello = os.environ.get('HELLO', '{"ok":{"app":"bimcraft"}}')
acts = [hello + '\n']
calls = []
i = 0
while i + 2 < len(a) + 0 or i + 3 <= len(a):
    tool, args, reply = a[i], a[i + 1], a[i + 2]
    i += 3
    calls.append(json.dumps({"jsonrpc": "2.0", "id": len(calls) + 1, "method": "tools/call", "params": {"name": tool, "arguments": json.loads(args)}}))
    if reply == '@close':
        acts.append({"close": True})
    elif reply == '@noreply':
        acts.append({"noreply": True})
    elif reply.startswith('@sleep:'):
        _, secs, line = reply.split(':', 2)
        acts.append({"sleep": float(secs), "then": line + '\n'})
    elif reply == '@skip':
        pass
    else:
        acts.append(reply + '\n')
p = subprocess.run([sys.executable, '/tmp/mcp-agent/bridge.py'] + pre + ['-t', '100000', json.dumps(acts), '@init'] + calls, capture_output=True, timeout=300)
for l in p.stdout.decode().splitlines():
    if l.startswith('OUT: '):
        try:
            v = json.loads(l[5:])
        except Exception:
            print(l[:800]); continue
        if v.get('id') == 0:
            continue
        if 'result' in v and isinstance(v['result'], dict) and 'content' in v['result']:
            for c in v['result']['content']:
                if 'data' in c:
                    c['data'] = c['data'][:20] + '...<%d>' % len(c['data'])
        print('OUT:', json.dumps(v, ensure_ascii=False)[:1500])
    elif 'RECV' in l or 'SENT' in l or 'C1 OPEN' in l:
        continue
    else:
        print(l[:1500])

