        assert_eq!(p(&[]).unwrap(), Args { read_only: false, file: None, connect: None });
        assert_eq!(p(&["--connect", "--read-only"]).unwrap().connect, Some(None));
        assert_eq!(p(&["--connect", "+80"]).unwrap().connect, Some(Some(80)));
        assert_eq!(p(&["--connect", "-1"]).unwrap_err(), "`-1` is not a port: a number up to 65535");
        assert_eq!(p(&["a", "b", "--bogus"]).unwrap_err(), USAGE);
        assert_eq!(p(&["--connect", "--connect"]).unwrap_err(), format!("`--connect`: {}", USAGE));
        assert!(p(&["--connect", "5555", "6666"]).unwrap_err().starts_with("a window has its own project"));
        assert_eq!(p(&["--read-only", "--read-only", "x"]).unwrap().file.as_deref(), Some("x"));
    }
}

//! JSON-RPC 2.0 as the server speaks it, and its tools, on either backend.

use super::{bridge::Bridge, local::Local, text};
use crate::json::{Map, Value};

/// Where the tools run: a session of the server's own, or a window's.
pub enum Backend {
    Local(Local),
    Bridge(Bridge),
}

impl Backend {
    fn execute(&mut self, cmd: &str, params: Value) -> Result<Value, String> {
        match self {
            Backend::Local(l) => l.execute(cmd, &params),
            Backend::Bridge(b) => b.execute(cmd, params),
        }
    }
    /// A script's results, one for each line run.
    fn script(&mut self, text: &str, atomic: bool) -> Result<Value, String> {
        match self {
            Backend::Local(l) => l.script(text, atomic),
            Backend::Bridge(b) => b.script(text, atomic),
        }
    }
    fn new_model(&mut self, args: Value) -> Result<Value, String> {
        match self {
            Backend::Local(l) => l.new_model(&args),
            Backend::Bridge(_) => Err(Bridge::REPLACES_PROJECT.to_string()),
        }
    }
    fn open(&mut self, path: &Value) -> Result<Value, String> {
        match self {
            Backend::Local(l) => l.open_tool(path),
            Backend::Bridge(_) => Err(Bridge::REPLACES_PROJECT.to_string()),
        }
    }
    fn instructions(&self) -> String {
        let (bridged, read_only) = match self {
            Backend::Local(l) => (false, l.read_only),
            Backend::Bridge(b) => (true, b.read_only || b.window_read_only),
        };
        let mut s = text::INSTRUCTIONS.to_string();
        if bridged {
            s.push_str(text::BRIDGE_NOTE);
        }
        if read_only {
            s.push_str(text::READ_ONLY_NOTE);
        }
        s
    }
}

/// The protocol versions the server speaks; any other asked for gets the last.
const PROTOCOL_VERSIONS: [&str; 3] = ["2024-11-05", "2025-03-26", "2025-06-18"];

const TOOL_NAMES: [&str; 10] = [
    "execute",
    "script",
    "list_commands",
    "inspect_model",
    "query_elements",
    "schedule",
    "render",
    "new_model",
    "open",
    "save",
];

/// The parameters `render` is sent: these, and only these, null where the agent gives none.
const RENDER_KEYS: [&str; 11] = [
    "azimuth",
    "ceiling",
    "elevation",
    "family",
    "height",
    "mode",
    "path",
    "type",
    "view",
    "wall_thickness",
    "width",
];

pub struct Server {
    pub backend: Backend,
}

type RpcErr = (i64, String);

fn obj(items: Vec<(&str, Value)>) -> Value {
    let mut m = Map::new();
    for (k, v) in items {
        m.insert(k, v);
    }
    Value::Obj(m)
}

fn error_reply(id: Value, code: i64, message: &str) -> Value {
    obj(vec![
        ("error", obj(vec![("code", Value::i(code)), ("message", Value::s(message))])),
        ("id", id),
        ("jsonrpc", Value::s("2.0")),
    ])
}

/// A tool's result: its text (or a picture and its caption), and whether it is an error.
fn tool_text(text: String, is_error: bool) -> Value {
    let mut items = vec![("content", Value::Arr(vec![obj(vec![("text", Value::Str(text)), ("type", Value::s("text"))])]))];
    if is_error {
        items.push(("isError", Value::Bool(true)));
    }
    obj(items)
}

fn tool_result(r: Result<Value, String>) -> Value {
    match r {
        Ok(v) => tool_text(v.sorted().to_pretty(), false),
        Err(e) => tool_text(e, true),
    }
}

impl Server {
    pub fn new(backend: Backend) -> Server {
        Server { backend }
    }

    /// The reply to a line (a message or a batch of them); none to notifications and replies.
    pub fn handle_line(&mut self, line: &str) -> Option<Value> {
        let v = match crate::json::parse(line) {
            Ok(v) => v,
            Err(e) => return Some(error_reply(Value::Null, -32700, &format!("parse error: {}", e))),
        };
        match v {
            Value::Arr(items) => {
                if items.is_empty() {
                    return Some(error_reply(Value::Null, -32600, "empty batch"));
                }
                let out: Vec<Value> = items.iter().filter_map(|m| self.handle_message(m)).collect();
                if out.is_empty() {
                    None
                } else {
                    Some(Value::Arr(out))
                }
            }
            m => self.handle_message(&m),
        }
    }

    fn handle_message(&mut self, m: &Value) -> Option<Value> {
        let Some(o) = m.as_obj() else {
            return Some(error_reply(Value::Null, -32600, "a message must be an object"));
        };
        let id = o.get("id").cloned();
        let Some(method) = o.get("method").and_then(|x| x.as_str()) else {
            // a reply to something of ours: there is nothing it answers
            if o.contains("result") || o.contains("error") {
                return None;
            }
            return Some(error_reply(id.unwrap_or(Value::Null), -32600, "missing `method`"));
        };
        // a notification is never answered, nor acted on
        let id = id?;
        match self.dispatch(method, o.get("params")) {
            Ok(result) => Some(obj(vec![("id", id), ("jsonrpc", Value::s("2.0")), ("result", result)])),
            Err((code, msg)) => Some(error_reply(id, code, &msg)),
        }
    }

    fn dispatch(&mut self, method: &str, params: Option<&Value>) -> Result<Value, RpcErr> {
        match method {
            "initialize" => {
                let asked = params.and_then(|p| p.get("protocolVersion")).and_then(|v| v.as_str());
                let version = match asked {
                    Some(v) if PROTOCOL_VERSIONS.contains(&v) => v,
                    _ => PROTOCOL_VERSIONS[PROTOCOL_VERSIONS.len() - 1],
                };
                Ok(obj(vec![
                    ("capabilities", obj(vec![("tools", obj(vec![("listChanged", Value::Bool(false))]))])),
                    ("instructions", Value::Str(self.backend.instructions())),
                    ("protocolVersion", Value::s(version)),
                    (
                        "serverInfo",
                        obj(vec![
                            ("name", Value::s("bimcraft")),
                            ("title", Value::s("BIMCraft")),
                            ("version", Value::s(crate::VERSION)),
                        ]),
                    ),
                ]))
            }
            "ping" => Ok(Value::obj()),
            "tools/list" => Ok(obj(vec![("tools", crate::json::parse(text::TOOLS).unwrap())])),
            "tools/call" => self.call_tool(params),
            _ => Err((-32601, format!("method `{}` not found", method))),
        }
    }

    fn call_tool(&mut self, params: Option<&Value>) -> Result<Value, RpcErr> {
        let Some(name) = params.and_then(|p| p.get("name")).and_then(|v| v.as_str()) else {
            return Err((-32602, "missing tool `name`".into()));
        };
        if !TOOL_NAMES.contains(&name) {
            return Err((-32602, format!("unknown tool `{}`", name)));
        }
        let args = match params.and_then(|p| p.get("arguments")) {
            None | Some(Value::Null) => Map::new(),
            Some(Value::Obj(m)) => m.clone(),
            Some(_) => return Err((-32602, format!("the arguments of `{}` must be an object", name))),
        };
        // a key given as null is as good as none
        let given = |k: &str| args.get(k).filter(|v| !v.is_null());
        let b = &mut self.backend;
        Ok(match name {
            "execute" => {
                let Some(command) = given("command") else {
                    return Err((-32602, "`execute` needs `command`".into()));
                };
                let command = command.as_str().unwrap_or("").to_string();
                let p = args.get("params").cloned().unwrap_or_else(Value::obj);
                tool_result(b.execute(&command, p))
            }
            "script" => {
                let Some(text) = given("text") else {
                    return Err((-32602, "`script` needs `text`".into()));
                };
                let text = text.as_str().unwrap_or("").to_string();
                let atomic = match given("atomic") {
                    None => false,
                    Some(Value::Bool(x)) => *x,
                    Some(v) => return Err((-32602, format!("`atomic` is true or false, not {}", v.to_compact()))),
                };
                tool_result(b.script(&text, atomic).map(|r| obj(vec![("results", r)])))
            }
            "list_commands" => {
                let filter = args.get("filter").and_then(|v| v.as_str());
                tool_result(Ok(list_commands(filter)))
            }
            "inspect_model" => tool_result(b.execute("inspect", Value::obj())),
            "query_elements" => tool_result(b.execute("elements", Value::Obj(args))),
            "schedule" => tool_result(b.execute("schedule", Value::Obj(args))),
            "render" => {
                let mut p = Map::new();
                for k in RENDER_KEYS {
                    p.insert(k, args.get(k).cloned().unwrap_or(Value::Null));
                }
                match b.execute("render", Value::Obj(p)) {
                    Ok(v) => render_content(&v),
                    Err(e) => tool_text(e, true),
                }
            }
            "new_model" => tool_result(b.new_model(Value::Obj(args))),
            "open" => {
                let Some(path) = given("path") else {
                    return Err((-32602, "`open` needs `path`".into()));
                };
                let path = path.clone();
                tool_result(b.open(&path))
            }
            "save" => tool_result(b.execute("save", Value::Obj(args))),
            _ => unreachable!(),
        })
    }
}

/// The catalog, or the commands whose id, label or a shortcut holds `filter` (in any case).
pub fn list_commands(filter: Option<&str>) -> Value {
    let all = crate::json::parse(crate::catalog::CATALOG).unwrap();
    let Some(f) = filter else { return all };
    let f = f.to_ascii_lowercase();
    let holds = |v: Option<&Value>| v.and_then(|x| x.as_str()).map(|s| s.to_ascii_lowercase().contains(&f)).unwrap_or(false);
    let list = all.as_arr().cloned().unwrap_or_default();
    Value::Arr(
        list.into_iter()
            .filter(|c| {
                holds(c.get("id"))
                    || holds(c.get("label"))
                    || c.get("aliases").and_then(|a| a.as_arr()).map(|a| a.iter().any(|x| holds(Some(x)))).unwrap_or(false)
            })
            .collect(),
    )
}

/// What `render` gives the agent: the picture, if it came back as one, and a line saying what it
/// is: `Level 1 (plan), 1600 x 1000 px`, `3D view from -45° round, 30° up, …`, `…, written to x.png`.
pub fn render_content(v: &Value) -> Value {
    let mut content = Vec::new();
    if let Some(png) = v.get("pngBase64").and_then(|x| x.as_str()) {
        content.push(obj(vec![
            ("data", Value::s(png)),
            ("mimeType", Value::s("image/png")),
            ("type", Value::s("image")),
        ]));
    }
    content.push(obj(vec![("text", Value::Str(render_caption(v))), ("type", Value::s("text"))]));
    obj(vec![("content", Value::Arr(content))])
}

pub fn render_caption(v: &Value) -> String {
    let kind = v.get("kind").and_then(|x| x.as_str());
    let mut s = if kind == Some("3D view") {
        let deg = |k: &str| v.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0);
        format!("3D view from {}° round, {}° up", deg("azimuth"), deg("elevation"))
    } else {
        let view = v.get("view").and_then(|x| x.as_str()).unwrap_or("");
        match kind {
            Some(k) => format!("{} ({})", view, k),
            None => view.to_string(),
        }
    };
    if let (Some(w), Some(h)) = (v.get("width").and_then(|x| x.as_u64()), v.get("height").and_then(|x| x.as_u64())) {
        s.push_str(&format!(", {} x {} px", w, h));
    }
    if let Some(p) = v.get("path").and_then(|x| x.as_str()) {
        s.push_str(&format!(", written to {}", p));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cap(s: &str) -> String {
        render_caption(&crate::json::parse(s).unwrap())
    }

    #[test]
    fn captions() {
        assert_eq!(cap(r#"{"kind":"plan","view":"Level 1","width":100,"height":80}"#), "Level 1 (plan), 100 x 80 px");
        assert_eq!(cap(r#"{"kind":"3D view","azimuth":-45.0,"elevation":30.0}"#), "3D view from -45° round, 30° up");
        assert_eq!(cap(r#"{"kind":"3D view","azimuth":1e20,"elevation":-0.0}"#), "3D view from 100000000000000000000° round, -0° up");
        assert_eq!(cap(r#"{"view":"L","width":100.5,"height":80}"#), "L");
        assert_eq!(cap(r#"{"path":"x.png"}"#), ", written to x.png");
        assert_eq!(cap(r#"{"view":"","kind":""}"#), " ()");
        assert_eq!(cap("5"), "");
    }

    #[test]
    fn filters() {
        let ids = |f: &str| -> Vec<String> {
            list_commands(Some(f)).as_arr().unwrap().iter().map(|c| c.get("id").unwrap().as_str().unwrap().to_string()).collect()
        };
        assert_eq!(ids("WA"), vec!["wall", "wall_by_face", "strip_footing", "water_size"]);
        assert_eq!(ids("fw"), vec!["strip_footing"]);
        assert!(ids("\u{212a}").is_empty());
    }
}

//! The headless backend: a session of the server's own, read-only with `--read-only`.
//!
//! Read-only is the agent's side of it: the project is opened as ever, then nothing the agent
//! asks may change it, step through its history, replace it or write over its file. A command
//! that would replace the project (or step through the history) is refused before it runs; one
//! that names the project's own file as its `path` too; anything else runs, and if it would have
//! made an undo step it is taken back and refused. Its errors come first, so a command given
//! wrong parameters says what is wrong with them.

use crate::json::{Map, Value};
use crate::session::{Session, Step, MAX_UNDO};

pub struct Local {
    pub s: Session,
    pub read_only: bool,
}

/// Why an agent may not change the project here.
const READ_ONLY_REASON: &str = "this MCP server was started with --read-only: start it without to edit";

/// The commands that put another project in place of this one.
const REPLACES: [&str; 4] = ["new", "open", "recover", "highrise"];

fn would(cid: &str, what: &str) -> String {
    format!("`{}` would {}, which is read-only for agents: {}", cid, what, READ_ONLY_REASON)
}

/// Whether two paths name one file: as the file system resolves them, or as written when it can't.
fn same_file(a: &str, b: &str) -> bool {
    let canon = |p: &str| std::fs::canonicalize(p).unwrap_or_else(|_| std::path::PathBuf::from(p));
    canon(a) == canon(b)
}

impl Local {
    pub fn new(read_only: bool) -> Local {
        Local { s: Session::new(), read_only }
    }

    /// Opens the FILE the server was started with; the error is the whole message.
    pub fn open_file(&mut self, path: &str) -> Result<(), String> {
        self.open(path).map(|_| ())
    }

    /// Opens a project or imports a file by its extension; a Revit import's error is a whole
    /// message, the path first, and the others say `open: `.
    fn open(&mut self, path: &str) -> Result<Value, String> {
        crate::commands::open_path(&mut self.s, path).map_err(|e| {
            if crate::rvt::is_revit_path(path) {
                e
            } else {
                format!("open: {}", e)
            }
        })
    }

    /// The `open` tool: `path` as the `open` command reads it, then the file by its extension.
    pub fn open_tool(&mut self, path: &Value) -> Result<Value, String> {
        if self.read_only {
            return Err(would("open", "replace the project"));
        }
        let mut m = Map::new();
        m.insert("path", path.clone());
        let path = crate::commands::params::opt_text(&Value::Obj(m), "open", "path")?.unwrap_or_default();
        self.open(&path)
    }

    /// The `new_model` tool: `new` with the agent's arguments.
    pub fn new_model(&mut self, args: &Value) -> Result<Value, String> {
        if self.read_only {
            return Err(would("new", "replace the project"));
        }
        self.s.execute("new", args)
    }

    /// Runs a command, as the agent may.
    pub fn execute(&mut self, cmd: &str, params: &Value) -> Result<Value, String> {
        if !self.read_only {
            return self.s.execute(cmd, params);
        }
        let Some((cid, _)) = crate::commands::resolve(cmd) else {
            return self.s.execute(cmd, params);
        };
        if REPLACES.contains(&cid.as_str()) {
            return Err(would(&cid, "replace the project"));
        }
        if matches!(cid.as_str(), "undo" | "redo") {
            return Err(would(&cid, "change the project"));
        }
        if let Some(own) = self.s.path.clone() {
            if cid == "save" {
                let target = match params.get("path") {
                    None | Some(Value::Null) => Some(own.clone()),
                    Some(Value::Str(p)) => Some(p.clone()),
                    Some(_) => None,
                };
                if target.map(|t| same_file(&t, &own)).unwrap_or(false) {
                    return Err(would("save", "write over the project's own file"));
                }
            } else if let Some(p) = params.get("path").and_then(|x| x.as_str()) {
                if same_file(p, &own) {
                    return Err(would(&cid, "use the project's own file (`path`)"));
                }
            }
        }
        // nothing an agent does here moves the history, so it is empty: a step made is a change
        let before = self.s.project.clone();
        let path = self.s.path.clone();
        let phase = (self.s.now_phase.clone(), self.s.now_option.clone());
        let r = self.s.execute(cmd, params);
        // a copy saved elsewhere leaves the project's file where it was
        self.s.path = path;
        if !self.s.undo.is_empty() || !self.s.redo.is_empty() {
            self.s.undo.clear();
            self.s.redo.clear();
            self.s.project = before;
            self.s.now_phase = phase.0;
            self.s.now_option = phase.1;
            return Err(would(&cid, "change the project"));
        }
        r
    }

    /// Runs a script a line at a time, stopping at the first that fails (or isn't JSON). With
    /// `atomic`, a failing line takes back all before it, and a script that goes through is one
    /// undo step, `Script`; it steps through a history of its own meanwhile.
    pub fn script(&mut self, text: &str, atomic: bool) -> Result<Value, String> {
        if !atomic {
            let mut results = Vec::new();
            for (n, raw) in text.lines().enumerate() {
                if let Some((id, params)) = parse_line(raw, n + 1)? {
                    let v = self.execute(&id, &params).map_err(|e| format!("line {} ({}): {}", n + 1, id, e))?;
                    results.push(v);
                }
            }
            return Ok(Value::Arr(results));
        }
        let before = self.s.project.clone();
        let path = self.s.path.clone();
        let phase = (self.s.now_phase.clone(), self.s.now_option.clone());
        let undo = std::mem::take(&mut self.s.undo);
        let redo = std::mem::take(&mut self.s.redo);
        let mut results = Vec::new();
        let mut replaced = false;
        let mut failed = None;
        for (n, raw) in text.lines().enumerate() {
            let (id, params) = match parse_line(raw, n + 1) {
                Ok(Some(x)) => x,
                Ok(None) => continue,
                Err(e) => {
                    failed = Some(e);
                    break;
                }
            };
            match self.execute(&id, &params) {
                Ok(v) => {
                    results.push(v);
                    let cid = crate::commands::resolve(&id).map(|(c, _)| c).unwrap_or_default();
                    if REPLACES.contains(&cid.as_str()) {
                        replaced = true;
                    }
                }
                Err(e) => {
                    failed = Some(format!("line {} ({}): {}", n + 1, id, e));
                    break;
                }
            }
        }
        if let Some(e) = failed {
            self.s.project = before;
            self.s.path = path;
            self.s.now_phase = phase.0;
            self.s.now_option = phase.1;
            self.s.undo = undo;
            self.s.redo = redo;
            return Err(e);
        }
        if !replaced {
            // the script's own steps become one; another project opened keeps its history
            let stepped = !self.s.undo.is_empty();
            self.s.undo = undo;
            if stepped {
                self.s.redo.clear();
                self.s.undo.push(Step { before, after: self.s.project.clone(), label: "Script".into() });
                if self.s.undo.len() > MAX_UNDO {
                    self.s.undo.remove(0);
                }
            } else {
                self.s.redo = redo;
            }
        }
        Ok(Value::Arr(results))
    }
}

/// One line of a script: `id {json}`; none for a blank line or a `#` comment.
fn parse_line(raw: &str, n: usize) -> Result<Option<(String, Value)>, String> {
    let t = raw.trim();
    if t.is_empty() || t.starts_with('#') {
        return Ok(None);
    }
    let (id, rest) = match t.find(char::is_whitespace) {
        Some(i) => (&t[..i], t[i..].trim()),
        None => (t, ""),
    };
    let params = if rest.is_empty() {
        Value::obj()
    } else {
        crate::json::parse(rest).map_err(|e| format!("line {}: bad JSON after `{}`: {}", n, id, e))?
    };
    Ok(Some((id.to_string(), params)))
}

//! The bridge (`mcp --connect [PORT]`): the tools run on the project a desktop window has open,
//! through its control port.
//!
//! The window listens on 127.0.0.1 and writes its port and a token to `bridge.json` beside the
//! favorites. Each request is one line of JSON (keys sorted) holding the token, and each reply
//! one line: `{"ok": result}` or `{"error": "message"}`. The first request is
//! `{"op": "hello", "token": …}`, answered `{"ok": {"app": "bimcraft", "read_only"?: true}}`;
//! then `{"op": "execute", "command", "params", "token"}` for a command and
//! `{"op": "script", "text", "atomic", "token"}` for a script, each with `"read_only": true`
//! when the server was started with --read-only. The window answers between its frames, so
//! the server waits for each reply as long as it takes.

use crate::json::{Map, Num, Value};
use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::path::PathBuf;

pub struct Bridge {
    stream: TcpStream,
    reader: BufReader<TcpStream>,
    token: String,
    /// Asked for with --read-only: each request says so.
    pub read_only: bool,
    /// The window lets agents only read its project (its hello said so).
    pub window_read_only: bool,
}

/// Where `bridge.json` is: beside the favorites, which `BIMCRAFT_FAVORITES` names, else in the
/// configuration folder (`$XDG_CONFIG_HOME/bimcraft`, else `~/.config/bimcraft`).
pub fn bridge_path() -> Option<PathBuf> {
    let set = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty());
    if let Some(f) = set("BIMCRAFT_FAVORITES") {
        return Some(PathBuf::from(f).with_file_name("bridge.json"));
    }
    if let Some(x) = set("XDG_CONFIG_HOME") {
        return Some(PathBuf::from(x).join("bimcraft").join("bridge.json"));
    }
    let home = set("HOME")?;
    Some(PathBuf::from(home).join(".config").join("bimcraft").join("bridge.json"))
}

/// The port and the token a bridge file holds, if it holds them.
fn read_bridge_file(path: &PathBuf) -> Option<(u16, String)> {
    let text = std::fs::read_to_string(path).ok()?;
    let v = crate::json::parse(&text).ok()?;
    let port = v.get("port").and_then(|p| p.as_u64()).filter(|p| *p <= u16::MAX as u64)? as u16;
    let token = v.get("token").and_then(|t| t.as_str()).filter(|t| !t.is_empty())?.to_string();
    Some((port, token))
}

/// Writes a value as JSON a piece at a time, as a serializer writing straight to the stream
/// does (a window that has gone is found by the write that fails, as it would be).
fn emit(w: &mut impl Write, v: &Value) -> std::io::Result<()> {
    match v {
        Value::Null => w.write_all(b"null"),
        Value::Bool(b) => w.write_all(if *b { b"true" } else { b"false" }),
        Value::Num(n) => {
            let s = match n {
                Num::U(u) => u.to_string(),
                Num::I(i) => i.to_string(),
                Num::F(f) => crate::json::fmt_f64(*f),
            };
            w.write_all(s.as_bytes())
        }
        Value::Str(s) => emit_str(w, s),
        Value::Arr(a) => {
            w.write_all(b"[")?;
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    w.write_all(b",")?;
                }
                emit(w, x)?;
            }
            w.write_all(b"]")
        }
        Value::Obj(m) => {
            w.write_all(b"{")?;
            for (i, (k, x)) in m.items.iter().enumerate() {
                if i > 0 {
                    w.write_all(b",")?;
                }
                emit_str(w, k)?;
                w.write_all(b":")?;
                emit(w, x)?;
            }
            w.write_all(b"}")
        }
    }
}

fn emit_str(w: &mut impl Write, s: &str) -> std::io::Result<()> {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    w.write_all(b"\"")?;
    let bytes = s.as_bytes();
    let mut start = 0;
    for (i, &b) in bytes.iter().enumerate() {
        let esc: Option<&[u8]> = match b {
            b'"' => Some(b"\\\""),
            b'\\' => Some(b"\\\\"),
            b'\n' => Some(b"\\n"),
            b'\r' => Some(b"\\r"),
            b'\t' => Some(b"\\t"),
            0x08 => Some(b"\\b"),
            0x0c => Some(b"\\f"),
            0..=0x1f => None,
            _ => continue,
        };
        if start < i {
            w.write_all(&bytes[start..i])?;
        }
        match esc {
            Some(e) => w.write_all(e)?,
            None => w.write_all(&[b'\\', b'u', b'0', b'0', HEX[(b >> 4) as usize], HEX[(b & 0xf) as usize]])?,
        }
        start = i + 1;
    }
    if start < bytes.len() {
        w.write_all(&bytes[start..])?;
    }
    w.write_all(b"\"")
}

fn obj(items: Vec<(&str, Value)>) -> Value {
    let mut m = Map::new();
    for (k, v) in items {
        m.insert(k, v);
    }
    Value::Obj(m).sorted()
}

impl Bridge {
    /// What `new_model` and `open` say on a window's project.
    pub const REPLACES_PROJECT: &'static str = "that would replace the project the window has open, which is the user's: an agent never starts or opens a project in a window; the user does, with File > New and File > Open (or run `bimcraft-cli mcp` without --connect for a project of the agent's own)";

    /// Finds the window (on `port`, or the bridge file's), connects and says hello.
    pub fn connect(port: Option<u16>, read_only: bool) -> Result<Bridge, String> {
        let path = bridge_path().ok_or_else(|| "there is no folder for the bridge file here: set BIMCRAFT_FAVORITES".to_string())?;
        let shown = path.display().to_string();
        let (file_port, token) = read_bridge_file(&path).ok_or_else(|| {
            format!("{}: no window has opened a control port (start one with `bimcraft --control 0`)", shown)
        })?;
        if let Some(p) = port {
            if p != file_port {
                return Err(format!(
                    "{} has the token of the window on port {}, not {}: start that window with `--control {}` again, or connect without a port",
                    shown, file_port, p, p
                ));
            }
        }
        let stream = TcpStream::connect(("127.0.0.1", file_port)).map_err(|e| {
            format!(
                "no window answers on port {}: {} (is it still open? the bridge file may be left from one that closed)",
                file_port, e
            )
        })?;
        let reader = BufReader::new(stream.try_clone().map_err(|e| e.to_string())?);
        let mut b = Bridge { stream, reader, token, read_only, window_read_only: false };
        let hello = obj(vec![("op", Value::s("hello")), ("token", Value::Str(b.token.clone()))]);
        let reply = b.request(&hello)?;
        if reply.get("app").and_then(|a| a.as_str()) != Some("bimcraft") {
            return Err(format!("port {} is not a BIMCraft window", file_port));
        }
        b.window_read_only = reply.get("read_only").and_then(|r| r.as_bool()) == Some(true);
        Ok(b)
    }

    /// Sends one request and waits for its reply: the result, or the window's error.
    fn request(&mut self, req: &Value) -> Result<Value, String> {
        let closed = |e: std::io::Error| format!("the window closed the connection ({})", e);
        emit(&mut self.stream, req).map_err(closed)?;
        self.stream.write_all(b"\n").map_err(closed)?;
        let mut line = String::new();
        let n = self.reader.read_line(&mut line).map_err(closed)?;
        if n == 0 {
            return Err("the window closed the connection".into());
        }
        let v = crate::json::parse(&line).map_err(|e| format!("the window's reply is not JSON: {}", e))?;
        if let Some(ok) = v.get("ok") {
            return Ok(ok.clone());
        }
        if let Some(e) = v.get("error").and_then(|e| e.as_str()) {
            return Err(e.to_string());
        }
        Err("the window's reply says neither ok nor error".into())
    }

    fn with_access(&self, mut items: Vec<(&'static str, Value)>) -> Value {
        if self.read_only {
            items.push(("read_only", Value::Bool(true)));
        }
        items.push(("token", Value::Str(self.token.clone())));
        obj(items)
    }

    /// A command, run on the window's session as a button runs it.
    pub fn execute(&mut self, cmd: &str, params: Value) -> Result<Value, String> {
        let req = self.with_access(vec![("command", Value::s(cmd)), ("op", Value::s("execute")), ("params", params)]);
        self.request(&req)
    }

    /// A script, which the window reads through before it runs; its results.
    pub fn script(&mut self, text: &str, atomic: bool) -> Result<Value, String> {
        let req = self.with_access(vec![("atomic", Value::Bool(atomic)), ("op", Value::s("script")), ("text", Value::s(text))]);
        self.request(&req)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn emits_as_compact() {
        let v = crate::json::parse(r#"{"a":[1,-2,0.5,"x\n\u0001é"],"b":{},"c":[],"d":null,"e":true}"#).unwrap();
        let mut out = Vec::new();
        emit(&mut out, &v).unwrap();
        assert_eq!(String::from_utf8(out).unwrap(), v.to_compact());
    }
}

