169	    /// Sends one request and waits for its reply: the result, or the window's error.
170	    fn request(&mut self, req: &Value) -> Result<Value, String> {
171	        let closed = |e: std::io::Error| format!("the window closed the connection ({})", e);
172	        emit(&mut self.stream, req).map_err(closed)?;
173	        self.stream.write_all(b"\n").map_err(closed)?;
174	        let mut line = String::new();
175	        let n = self.reader.read_line(&mut line).map_err(|e| match e.kind() {
176	            // a reply that is not text, or none in time: the window is there but said nothing
177	            std::io::ErrorKind::InvalidData | std::io::ErrorKind::TimedOut | std::io::ErrorKind::WouldBlock => {
178	                format!("the window did not answer: {}", e)
179	            }
180	            _ => closed(e),
181	        })?;
182	        if n == 0 {
183	            return Err("the window closed the connection".into());
184	        }
185	        let v = crate::json::parse(&line).map_err(|e| format!("the window's reply is not JSON: {}", e))?;
186	        if let Some(ok) = v.get("ok") {
187	            return Ok(ok.clone());
188	        }
189	        if let Some(e) = v.get("error").and_then(|e| e.as_str()) {
190	            return Err(e.to_string());
191	        }
192	        Err("the window's reply says neither ok nor error".into())
193	    }
